<script setup lang="ts">import { computed } from 'vue'; import { useAppStore } from '@/stores/app'; import TaskRow from '@/components/task/TaskRow.vue'; import type { Category } from '@/types'; const props=defineProps<{category:Category}>(); const app=useAppStore(); const categoryTasks=computed(()=>app.tasks.filter(t=>t.categoryId===props.category.id))</script>
<template><div class="category-content-grid"><section class="panel span-2"><div class="panel-header"><div><h2>Category summary</h2><p>Current work and delivery progress</p></div></div><div class="summary-strip"><div><strong>{{categoryTasks.length}}</strong><span>Total tasks</span></div><div><strong>{{categoryTasks.filter(t=>t.status==='In progress').length}}</strong><span>In progress</span></div><div><strong>{{categoryTasks.filter(t=>t.status==='Done').length}}</strong><span>Completed</span></div><div><strong>{{categoryTasks.filter(t=>t.dueDate).length}}</strong><span>With due dates</span></div></div><div class="task-list"><TaskRow v-for="task in categoryTasks.slice(0,6)" :key="task.id" :task="task"/></div></section><section class="panel"><div class="panel-header"><div><h2>About</h2><p>Category details</p></div></div><dl class="details-list"><div><dt>Lead</dt><dd>{{category.lead.name}}</dd></div><div><dt>Key</dt><dd>{{category.key}}</dd></div><div><dt>Updated</dt><dd>{{category.updatedAt}}</dd></div><div><dt>Workspace</dt><dd>FlowForge Platform</dd></div></dl></section></div></template>
